def threeSumClosest(nums, target):
    n = len(nums)
    closest = nums[0] + nums[1] + nums[2]
    for i in range(n):
        for j in range(i + 1, n):
            for k in range(j + 1, n):
                cur = nums[i] + nums[j] + nums[k]
                if abs(cur - target) < abs(closest - target):
                    closest = cur
    return closest

