def threeSumClosest(nums, target):
    nums.sort()
    closest = nums[0] + nums[1] + nums[2]
    n = len(nums)
    for i in range(n - 2):
        left, right = i + 1, n - 1
        while left < right:
            cur = nums[i] + nums[left] + nums[right]
            if cur == target:
                return cur
            if abs(cur - target) < abs(closest - target):
                closest = cur
            if cur < target:
                left += 1
            else:
                right -= 1
    return closest

